package com.hozefa.threepattipro.nativeapp;
import static org.junit.Assert.*;import org.junit.Test;import java.util.*;
public class OnlineIntegrationTest {
 @Test public void explicitSessionCannotLeakIntoManualWindow(){Map<String,Object> s=FirebaseGateway.map("id","manual","startTime","2026-10-20T10:00:00Z");Map<String,Object> r=FirebaseGateway.map("source","online","sessionId","online","timestamp","2026-10-20T11:00:00Z");assertFalse(SessionMembership.includes(r,s));r.put("sessionId","manual");assertTrue(SessionMembership.includes(r,s));}
 @Test public void legacyTimestampMembershipPreserved(){Map<String,Object> s=FirebaseGateway.map("id","manual","startTime","2026-10-20T10:00:00Z");assertTrue(SessionMembership.includes(FirebaseGateway.map("timestamp","2026-10-20T11:00:00Z"),s));s.put("source","online");assertFalse(SessionMembership.includes(FirebaseGateway.map("timestamp","2026-10-20T11:00:00Z"),s));}
 @Test public void humanLifetimeStatsRecognizeComputerBidderWithoutAddingBotsToRoster(){Map<String,Object> r=FirebaseGateway.map("source","online","type","hukum","hukumId","bot_2","participants",Arrays.asList(FirebaseGateway.map("kind","bot","playerId","bot_2")),"playerIds",Arrays.asList("human"),"partnerIds",Arrays.asList("human"),"result","win","scoreChanges",FirebaseGateway.map("human",180,"bot_2",360));assertEquals(1,AdvancedAnalytics.result(r,"human"));AdvancedAnalytics.Report report=new AdvancedAnalytics.Report(Arrays.asList(FirebaseGateway.map("id","human","name","Human")),Arrays.asList(r),Collections.emptyList());assertEquals(Collections.singleton("human"),report.players.keySet());}
 @Test public void currentManualScopeDoesNotPickNewerOnlineSession(){Map<String,Object> manual=FirebaseGateway.map("id","manual","startTime","2026-10-20T10:00:00Z"),online=FirebaseGateway.map("id","online","source","online","startTime","2026-10-20T11:00:00Z");Map<String,Object> r=FirebaseGateway.map("type","hukum","sessionId","manual","timestamp","2026-10-20T10:30:00Z");assertEquals(1,AdvancedAnalytics.scope(Arrays.asList(r),Arrays.asList(manual,online),"current").size());}
}
